-- NFS-e — carga completa da NBS (Nomenclatura Brasileira de Serviços) v2.0.
-- Continuação da 20260903182000_nfse_catalogos_tributacao_e_nbs.sql, que deixou
-- `nfse_codigos_nbs` com 1 único código (o único confirmado até então contra o governo).
--
-- FONTE (leia antes de confiar)
-- Tabela oficial "NBS 2.0" publicada pelo MDIC (Ministério do Desenvolvimento, Indústria,
-- Comércio e Serviços), a mesma pasta responsável por manter/atualizar a nomenclatura:
--   Página:  https://www.gov.br/mdic/pt-br/assuntos/sdic/comercio-e-servicos/nbs-nomenclatura-brasileira-de-servicos
--   Arquivo: https://www.gov.br/mdic/pt-br/images/REPOSITORIO/scs/decos/NBS/NBS_2-0.csv
--            (nome real no HTML vem com espaços mascarados por "_"; é o CSV oficial linkado
--             na própria página, ao lado do PDF "Anexo I – NBS 2.0")
--   Baixado: 2026-09-07. Página do MDIC mostra "Atualizado em 29/01/2026" — é a versão
--            vigente (não há NBS 3.0 publicada; a última revisão de conteúdo é de 6/12/2018).
--
-- Por que confiamos: domínio .gov.br do próprio ministério dono da nomenclatura (não é
-- agregador terceiro), e o CSV bate byte-a-byte com o único dado que já tínhamos confirmado
-- em produção: a linha "1.2001.60.00;Serviços de manutenção e reparação de maquinários e
-- equipamentos de uso comercial" gera exatamente cNBS 120016000, com a MESMA descrição já
-- gravada como `verificado = true` (nota autorizada da Glacial Cold, 02/09/2026).
--
-- ESTRUTURA DO CÓDIGO (cNBS = 9 dígitos, sem pontos)
-- O CSV vem em 4 níveis hierárquicos, separados por ".": capítulo (1 dígito), posição
-- (4 dígitos), subposição (1 ou 2 dígitos) e código/item final (2 dígitos). Só o nível FOLHA
-- (4 segmentos, com o último tendo 2 dígitos) é um cNBS válido de 9 dígitos — os demais são
-- agrupadores hierárquicos (capítulo/posição/subposição), inclusive 10 linhas do CSV com
-- subposição de 1 dígito que são intermediárias e têm filhos de 2 dígitos (essas NÃO entram).
-- Ex.: "1.0101.11.00" → concatenando os 4 segmentos sem os pontos → "101011100" (9 dígitos).
-- Verificado: das 1237 linhas de dados do CSV, 920 são folhas de 9 dígitos (127 capítulos/
-- posições de 2 segmentos + 180 subposições de 3 segmentos + 10 subposições intermediárias
-- de 4 segmentos ficam de fora; 920 códigos finais entram).
--
-- IDEMPOTÊNCIA: UPSERT por código, nunca DELETE. `verificado` nunca é rebaixado (mesma regra
-- da migration anterior). `fonte` só é atualizada para linhas que AINDA NÃO foram verificadas
-- manualmente — se uma linha já foi confirmada contra o governo (verificado=true antes deste
-- seed), a nota de proveniência específica daquela verificação é preservada.

ON CONFLICT (codigo) DO UPDATE
  SET descricao  = EXCLUDED.descricao,
      fonte      = CASE WHEN public.nfse_codigos_nbs.verificado
                        THEN public.nfse_codigos_nbs.fonte
                        ELSE EXCLUDED.fonte
                   END,
      verificado = public.nfse_codigos_nbs.verificado OR EXCLUDED.verificado,
      ativo      = true;

-- ============================================================
-- Conferência de carga (falha alto se o seed não bater)
-- ============================================================
DO $seed_nbs$
DECLARE
  v_nbs      int;
  v_ancora   text;
BEGIN
  SELECT count(*) INTO v_nbs FROM public.nfse_codigos_nbs;
  SELECT descricao INTO v_ancora FROM public.nfse_codigos_nbs WHERE codigo = '120016000';

  IF v_nbs < 920 THEN
    RAISE EXCEPTION 'Seed de nfse_codigos_nbs incompleto: % linhas (esperado >= %).', v_nbs, 920;
  END IF;
  IF v_ancora IS DISTINCT FROM 'Serviços de manutenção e reparação de maquinários e equipamentos de uso comercial' THEN
    RAISE EXCEPTION 'Ancora de conferencia falhou: 120016000 deveria manter a descricao ja verificada, veio %.', coalesce(v_ancora, '<nulo>');
  END IF;

  RAISE NOTICE 'Catalogo NBS semeado: nfse_codigos_nbs=% linhas (folhas de 9 digitos da NBS 2.0/MDIC).', v_nbs;
END $seed_nbs$;

COMMENT ON TABLE public.nfse_codigos_nbs IS
  'Catálogo GLOBAL (sem company_id) da Nomenclatura Brasileira de Serviços — cNBS, 9 dígitos (ex.: 120016000 = 1.2001.60.00). Carga completa (920 códigos-folha) a partir da tabela oficial NBS 2.0 do MDIC (ver migration 20260907120000_nfse_catalogo_nbs_completo.sql para a fonte exata); cNBS não é obrigatório na DPS (só pesa em exportação de serviço). `verificado=true` marca códigos confirmados contra uma nota autorizada em produção, além da carga oficial.';
